; NMRA DCC three-byte packet for a booster; one packet per host word (address | instruction << 8 | check << 16), acknowledged
; Generated by escgen from protocols/dcc_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: NMRA S-9.1 Electrical Standards for Digital Command Control: 1 bit half-period 58 us (52 to 64), 0 bit half-period 100 us nominal (95 to 9900)
; Reference: NMRA S-9.2 Communications Standards: preamble of at least 14 one-bits, packet start bit 0, data byte start bits 0, error detection byte (XOR), packet end bit 1
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ H1, CLK_KHZ * 58 // 1000
.equ H0, CLK_KHZ * 100 // 1000
.default PIN_DCC, 0
.equ P_DCC, 1 << PIN_DCC

.own  PIN_DCC, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_DCC, 0, P_DCC             ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    EMIT  P_DCC, P_DCC, P_DCC         ; pre
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    MOV   r0, r1                      ; 8 bits, MSB first, each zero or one
    SHL   r0, 24                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit1:
    SHL   r0, 1                       ; C = the next bit
    JC    one2
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    JMP   next3
one2:
    EMIT  P_DCC, P_DCC, P_DCC         ; one
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
next3:
    ADDI  r3, 1
    CMPI  r3, 8                       ; Z after the last bit
    JNZ   bit1
    SHR   r1, 8                       ; next field
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    MOV   r0, r1                      ; 8 bits, MSB first, each zero or one
    SHL   r0, 24                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit4:
    SHL   r0, 1                       ; C = the next bit
    JC    one5
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    JMP   next6
one5:
    EMIT  P_DCC, P_DCC, P_DCC         ; one
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
next6:
    ADDI  r3, 1
    CMPI  r3, 8                       ; Z after the last bit
    JNZ   bit4
    SHR   r1, 8                       ; next field
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    MOV   r0, r1                      ; 8 bits, MSB first, each zero or one
    SHL   r0, 24                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit7:
    SHL   r0, 1                       ; C = the next bit
    JC    one8
    EMIT  P_DCC, P_DCC, P_DCC         ; zero
    ADDT  H0
    EMIT  P_DCC, 0, P_DCC
    ADDT  H0
    JMP   next9
one8:
    EMIT  P_DCC, P_DCC, P_DCC         ; one
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
next9:
    ADDI  r3, 1
    CMPI  r3, 8                       ; Z after the last bit
    JNZ   bit7
    EMIT  P_DCC, P_DCC, P_DCC         ; one
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    EMIT  P_DCC, P_DCC, P_DCC         ; one
    ADDT  H1
    EMIT  P_DCC, 0, P_DCC
    ADDT  H1
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet
